import itertools

BITS = ("Ath", "Con", "Str", "Rare", "Unw")
# Predicates: Ath=athlete, Con=contestant (took part), Str=strong,
# Rare=seldom gets sick, Unw=feels unwell.
TYPES = [dict(zip(BITS, bits)) for bits in itertools.product([0, 1], repeat=len(BITS))]
MAX_N = 3  # bounded finite-model search


def premises_hold(model):
    # P1: every contestant is an athlete and strong.
    # P2: every strong athlete seldom gets sick.
    # P3: some athlete is unwell and did not take part.
    for p in model:
        if p["Con"] and not (p["Ath"] and p["Str"]):
            return False
        if p["Str"] and not p["Rare"]:
            return False
    return any(p["Ath"] and p["Unw"] and not p["Con"] for p in model)


def opt_A(m):  # some contestants who are unwell seldom get sick
    return any(p["Con"] and p["Unw"] and p["Rare"] for p in m)


def opt_C(m):  # some contestants who are rarely sick feel unwell
    return any(p["Con"] and p["Rare"] and p["Unw"] for p in m)


def opt_D(m):  # some strong athletes feel unwell
    return any(p["Str"] and p["Unw"] for p in m)


def describe(model):
    out = []
    for i, p in enumerate(model):
        flags = [k for k in BITS if p[k]]
        out.append(f"x{i + 1}:{{{','.join(flags) if flags else 'none'}}}")
    return " ".join(out)


total = 0
mismatch_AC = 0
counter = {"A": None, "C": None, "D": None}
counts = {"A": 0, "C": 0, "D": 0}

for n in range(1, MAX_N + 1):
    for model in itertools.product(TYPES, repeat=n):
        model = list(model)
        if not premises_hold(model):
            continue
        total += 1
        a, c, d = opt_A(model), opt_C(model), opt_D(model)
        if a != c:
            mismatch_AC += 1
        for name, val in (("A", a), ("C", c), ("D", d)):
            if not val:
                counts[name] += 1
                if counter[name] is None:
                    counter[name] = (n, describe(model))

print(f"Premise-satisfying models checked (size 1..{MAX_N}): {total}")
print(f"Models where A and C disagree (should be 0): {mismatch_AC}")
print(f"Premise models falsifying A: {counts['A']}")
print(f"Premise models falsifying C: {counts['C']}")
print(f"Premise models falsifying D: {counts['D']}")

for name in ("A", "C", "D"):
    if counter[name]:
        n, desc = counter[name]
        print(f"Counterexample for {name} (size {n}): {desc}")

print("Option B: 'very few' is a vague quantity, not formalizable -> UNSUPPORTED")

if counter["A"] is not None:
    print("CHECK PASS: option A is not entailed by the premises (finite counterexample found).")
else:
    print("CHECK FAIL: no counterexample to A found in the bounded search.")

print("CHECK UNKNOWN: uniqueness not settled. C is formally identical to A and D is also "
      "falsified by a premise model, so the premises do not single out A as the only "
      "non-derivable option. Bounded search (size <= 3) can refute entailment but cannot "
      "prove entailment for a universal claim.")
